const conDanio = cuerpo.con_danio === true || texto(cuerpo.con_danio).toLowerCase() === 'true';
const observaciones = texto(cuerpo.observaciones).slice(0, 1000);

if (!prestamo) return respuestaError(404, 'PRESTAMO_NO_ENCONTRADO', 'El préstamo no existe.');
if (prestamo.estado !== 'activo') {
  return respuestaError(409, 'PRESTAMO_YA_DEVUELTO', `El préstamo #${prestamo.id} ya fue devuelto (${prestamo.fecha_devolucion}).`);
}
if (conDanio && observaciones.length < LARGO_MINIMO_DESCRIPCION_DANIO) {
  return respuestaError(
    422,
    'DESCRIPCION_REQUERIDA',
    `Describe el daño (mínimo ${LARGO_MINIMO_DESCRIPCION_DANIO} caracteres): la IA lo usa para clasificar la incidencia.`,
  );
}

return [{ json: { ok: true, id: prestamo.id, con_danio: conDanio, observaciones } }];

// =====================================================================
//  Respuesta de la devolución (incluye el triaje de la incidencia de daño)
// =====================================================================
// Resume en una frase el resultado del triaje y sus efectos en otros módulos
const describirTriaje = (resultado) => {
  if (!resultado.clasificada) return `quedó pendiente de triaje manual (${resultado.error})`;
  const incidencia = resultado.incidencia;
  const quien = resultado.origen === 'manual' ? 'clasificada manualmente' : 'clasificada por la IA';
  const partes = [
    `${quien} como ${incidencia.categoria_nombre}, prioridad ${incidencia.prioridad}, asignada a ${incidencia.area_nombre}`,
  ];
  const efectos = resultado.efectos ?? {};
  partes.push(...(efectos.cambios ?? []));
  if (efectos.reservas_afectadas?.length) {
    partes.push(`${efectos.reservas_afectadas.length} reserva(s) futura(s) afectada(s): conviene reasignarlas`);
  }
  return partes.join('. ');
};
const devolucion = $('Registrar devolución').first().json;
const { prestamo, recurso, incidencia_id: incidenciaId } = devolucion;

let triaje = null;
if (incidenciaId) {
  const resultado = $input.first().json;
  triaje =
    resultado.encontrada === undefined
      ? { clasificada: false, error: resultado.error ?? 'el triaje no se pudo ejecutar', incidencia: null }
      : resultado;
}

const partes = [
  `Devolución registrada: ${prestamo.recurso_nombre} quedó ${recurso.estado === 'disponible' ? 'disponible' : `en ${recurso.estado}`}.`,
];
if (incidenciaId) partes.push(`Se creó la incidencia #${incidenciaId}: ${describirTriaje(triaje)}.`);

return [
  {
    json: {
      status: 200,
      body: { ok: true, data: { prestamo, recurso, incidencia_id: incidenciaId, triaje }, message: partes.join(' ') },
    },
  },
];

// =====================================================================
//  Traduce los errores de PostgreSQL a respuestas claras.
//  Las restricciones de la base de datos son la última barrera de
//  integridad: si dos peticiones simultáneas se saltan una regla, la base
//  de datos rechaza la segunda y aquí se explica el motivo al usuario.
// =====================================================================
const RESTRICCIONES = {
  reservas_sin_solapamiento: [409, 'CONFLICTO_HORARIO', 'El espacio ya tiene una reserva activa que se cruza con ese horario.'],
  espacios_codigo_unico: [409, 'CODIGO_DUPLICADO', 'Ya existe un espacio con ese código.'],
  recursos_codigo_unico: [409, 'CODIGO_DUPLICADO', 'Ya existe un recurso con ese código.'],
  prestamos_un_activo_por_recurso: [409, 'RECURSO_YA_PRESTADO', 'El recurso ya tiene un préstamo activo.'],
  recursos_espacio_id_fkey: [422, 'ESPACIO_INEXISTENTE', 'El espacio indicado no existe.'],
  espacios_capacidad_positiva: [422, 'CAPACIDAD_INVALIDA', 'La capacidad debe ser mayor que cero.'],
  reservas_rango_horario: [422, 'HORARIO_INVALIDO', 'La hora de fin debe ser posterior a la de inicio.'],
  prestamos_limite_posterior: [422, 'FECHA_INVALIDA', 'La fecha límite debe ser posterior a la fecha del préstamo.'],
  incidencias_clasificacion_completa: [422, 'CLASIFICACION_INCOMPLETA', 'La clasificación requiere categoría, prioridad y área.'],
};

const fallo = $input.first().json;
const detalle = `${fallo.message ?? ''} ${fallo.error?.description ?? ''}`;

const restriccion = Object.keys(RESTRICCIONES).find((nombre) => detalle.includes(nombre));
if (restriccion) {
  const [status, code, message] = RESTRICCIONES[restriccion];
  return [{ json: { status, body: { ok: false, error: { code, message, details: [{ regla: 'BD', mensaje: restriccion }] } } } }];
}

const sinConexion = /Connection refused|ECONNREFUSED|Host not found|ENOTFOUND|timed out/i.test(detalle);
return [
  {
    json: {
      status: sinConexion ? 503 : 500,
      body: {
        ok: false,
        error: {
          code: sinConexion ? 'BD_NO_DISPONIBLE' : 'ERROR_BASE_DE_DATOS',
          message: sinConexion
            ? 'La base de datos no está disponible en este momento.'
            : 'No fue posible completar la operación en la base de datos.',
          details: [{ regla: 'BD', mensaje: String(fallo.message ?? '').slice(0, 300) }],
        },
      },
    },
  },
];

// =====================================================================
//  Estado de los servicios: base de datos y configuración de la IA.
//  Con ?ia=1 además se hace una consulta real de prueba al modelo.
// =====================================================================
const bd = $input.first().json;
const consulta = $('GET /salud').first().json.query ?? {};
const proveedor = String($env.AI_PROVIDER || 'anthropic').trim().toLowerCase();
const modelo = $env.AI_MODEL || (proveedor === 'anthropic' ? 'claude-opus-5-5' : 'llama3.2');

const ia = {
  proveedor,
  modelo,
  configurada: proveedor === 'anthropic' ? Boolean($env.AI_API_KEY) : proveedor === 'openai',
  endpoint:
    proveedor === 'openai'
      ? $env.AI_BASE_URL || 'http://host.docker.internal:11434/v1'
      : $env.AI_BASE_URL || 'https://api.anthropic.com',
};

return [
  {
    json: {
      probarIa: ['1', 'true', 'si'].includes(String(consulta.ia ?? '').toLowerCase()),
      data: {
        servicio: 'ok',
        hora_campus: bd.hora_campus,
        base_de_datos: { conectada: true, registros: bd.registros },
        ia,
      },
    },
  },
];

// Consulta mínima para comprobar que el proveedor de IA responde
return [
  {
    json: {
      tarea: 'prueba_conexion',
      sistema: 'Eres un verificador de conexión. Responde solo con el JSON solicitado.',
      mensaje: 'Confirma que recibiste este mensaje respondiendo con estado "listo".',
      esquema: {
        type: 'object',
        additionalProperties: false,
        required: ['estado'],
        properties: { estado: { type: 'string', enum: ['listo'] } },
      },
      max_tokens: 2000,
      inicio: Date.now(),
    },
  },
];

// Agrega el resultado de la prueba real de IA al estado de los servicios
const salud = $('Estado de los servicios').first().json.data;
const inicio = $('Consulta de prueba').first().json.inicio;
const ia = $input.first().json;

const prueba = {
  ok: ia.ok === true && ia.datos?.estado === 'listo',
  latencia_ms: Date.now() - inicio,
  modelo_respondio: ia.modelo ?? null,
  error: ia.ok === true ? null : `${ia.error ?? 'sin respuesta'}${ia.detalle ? `: ${ia.detalle}` : ''}`,
};

return [{ json: { data: { ...salud, ia: { ...salud.ia, prueba } } } }];

